html:
{%- import "costeo_yelke/templates/print/oc_yelke.html" as oc -%}
{#- Recibo de taller: prendas o piezas que entregó un taller y la materia prima que consumió. Diseño: templates/print/oc_yelke.html -#}
{{ oc.estilos() }}
{{ oc.membrete_encabezado(doc, no_letterhead, print_settings, "Recibo de taller") }}
<div class="pdf-container">
{{ oc.marca_borrador(doc) }}
{{ oc.datos(doc, {"etiqueta": "Taller", "nombre": doc.supplier_name or doc.supplier, "rfc": rfc_tercero("Supplier", doc.supplier), "direccion": direccion_lineas(doc.supplier_address)},
    [("Fecha de recepción", fecha_corta(doc.posting_date)),
     ("Orden de maquila", (doc.items[0].purchase_order if doc.items else None)),
     ("Encargo", (doc.items[0].subcontracting_order if doc.items else None)),
     ("Recibido en", doc.set_warehouse),
     ("Piezas", cantidad_uom(doc.total_qty) if doc.total_qty else None)]) }}
{%- set rechazo = doc.items | selectattr("rejected_qty") | list | length > 0 %}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Producto</th>
        <th class="text-right" style="width:24mm">Recibido</th>
        {% if rechazo %}<th class="text-right" style="width:22mm">Rechazado</th>{% endif %}
        <th class="text-right" style="width:24mm">Costo unitario</th>
        <th class="text-right" style="width:27mm">Importe</th>
    </tr></thead>
    <tbody>
    {% for row in doc.items %}
        <tr>
            <td class="muted">{{ row.idx }}</td>
            <td>{{ oc.celda_articulo(row, con_descripcion=false) }}</td>
            <td class="num">{{ cantidad_uom(row.qty, row.stock_uom) }}</td>
            {% if rechazo %}<td class="num">{{ cantidad_uom(row.rejected_qty, row.stock_uom) if row.rejected_qty else "—" }}</td>{% endif %}
            <td class="num">{{ row.get_formatted("rate", doc) }}</td>
            <td class="num"><b>{{ row.get_formatted("amount", doc) }}</b></td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{{ oc.total_simple("Total", doc.get_formatted("total")) }}
{% if doc.supplied_items %}
{{ oc.seccion("Materia prima consumida") }}
<table class="items-table">
    <thead><tr>
        <th style="width:6mm">#</th><th>Material</th>
        <th>Para</th>
        <th class="text-right" style="width:30mm">Consumido</th>
    </tr></thead>
    <tbody>
    {% for rm in doc.supplied_items %}
        <tr>
            <td class="muted">{{ loop.index }}</td>
            <td><div class="item-title">{{ rm.item_name or rm.rm_item_code }}</div><div class="item-code"><span class="k">Código de producto:</span> {{ rm.rm_item_code }}</div></td>
            <td class="muted">{{ rm.main_item_code }}</td>
            <td class="num">{{ cantidad_uom(rm.consumed_qty, rm.stock_uom) }}</td>
        </tr>
    {% endfor %}
    </tbody>
</table>
{% endif %}
{{ oc.cierre(doc, mostrar_pagos=false, mostrar_totales=false) }}
</div>
{{ oc.membrete_pie(doc, no_letterhead, print_settings) }}
